/**
 * 權杖預檢（本機解碼，不呼叫 Google）：格式、簽發者、效期、來源不符者直接拒絕，
 * 避免任何人大量送假請求耗盡網路呼叫配額。簽章仍由 tokeninfo 正式驗證。
 */
function idTokenPrecheck_(tok) {
  const parts = String(tok).split('.');
  if (parts.length !== 3 || tok.length > 4096) throw new Error('身分權杖格式不正確');
  let p;
  try { p = JSON.parse(Utilities.newBlob(Utilities.base64DecodeWebSafe(parts[1] + '==='.slice((parts[1].length + 3) % 4))).getDataAsString()); }
  catch (e) { throw new Error('身分權杖格式不正確'); }
  if (['accounts.google.com', 'https://accounts.google.com'].indexOf(p.iss) < 0) throw new Error('身分權杖簽發者不正確');
  if (!(Number(p.exp) * 1000 > Date.now())) throw new Error('身分權杖已過期，請重新整理網頁');
  const aud = prop_('FRONT_AUD');
  if (aud && p.aud !== aud && !(WEB_CLIENT_ID && p.aud === WEB_CLIENT_ID)) throw new Error('身分權杖來源不正確');
}
