/* ---------------- 資料庫自動備份 ----------------
 * 每週日凌晨 3 點把資料庫試算表複製一份到「督導查核系統備份」資料夾，保留最近 12 份。
 */
const BACKUP_KEEP = 12;
function backupFolder_() {
  let folder = prop_('BACKUP_FOLDER_ID');
  if (!folder) {
    const r = driveFetch_('https://www.googleapis.com/drive/v3/files?fields=id', { method: 'post', contentType: 'application/json',
      payload: JSON.stringify({ name: '督導查核系統備份', mimeType: 'application/vnd.google-apps.folder' }) });
    folder = JSON.parse(r.getContentText()).id; setProp_('BACKUP_FOLDER_ID', folder);
  }
  return folder;
}
function backupNow_() {
  const folder = backupFolder_();
  const name = '督導查核系統資料庫_備份_' + Utilities.formatDate(new Date(), TZ, 'yyyyMMdd_HHmm');
  const cp = JSON.parse(driveFetch_('https://www.googleapis.com/drive/v3/files/' + prop_('DB_ID') + '/copy?fields=id,name', {
    method: 'post', contentType: 'application/json', payload: JSON.stringify({ name: name, parents: [folder] }) }).getContentText());
  // 只保留最近 BACKUP_KEEP 份（舊的移到垃圾桶，30 天內可救回）
  const q = encodeURIComponent("'" + folder + "' in parents and trashed=false and name contains '督導查核系統資料庫_備份_'");
  const list = JSON.parse(driveFetch_('https://www.googleapis.com/drive/v3/files?q=' + q + '&orderBy=createdTime desc&fields=files(id,name)&pageSize=100').getContentText()).files || [];
  const old = list.slice(BACKUP_KEEP);
  old.forEach(f => driveFetch_('https://www.googleapis.com/drive/v3/files/' + f.id, { method: 'patch', contentType: 'application/json', payload: JSON.stringify({ trashed: true }) }));
  setProp_('BACKUP_LAST', nowStr_() + '｜' + cp.name);
  return { name: cp.name, kept: Math.min(list.length, BACKUP_KEEP), trashed: old.length };
}
/** 每週排程 */
function backupJob() { backupNow_(); }
/** 設定每週自動備份並立即備份一次（系統維護） */
function apiBackupSetup(args, user) {
  ScriptApp.getProjectTriggers().filter(t => t.getHandlerFunction() === 'backupJob').forEach(t => ScriptApp.deleteTrigger(t));
  if (args.off) return { ok: true, auto: false };
  ScriptApp.newTrigger('backupJob').timeBased().onWeekDay(ScriptApp.WeekDay.SUNDAY).atHour(3).create();
  const r = backupNow_(); log_(user.Email, '資料庫備份', '', r);
  return Object.assign({ auto: true }, r);
}

/* ---------------- 各帳號操作紀錄 ---------------- */
/** 登入紀錄：每個帳號每天只記第一次開啟系統 */
function logLogin_(user) {
  try {
    const k = 'login|' + String(user.Email).toLowerCase() + '|' + ymd_(new Date()), cache = CacheService.getScriptCache();
    if (cache.get(k)) return;
    cache.put(k, '1', 21600);
    log_(user.Email, '登入', '', '');
  } catch (e) { /* 記錄失敗不影響使用 */ }
}
/**
 * 查詢操作紀錄（帳號管理）：args = {email, from, to, q, limit}
 *   回傳符合條件的紀錄（新到舊，最多 limit 筆）及各帳號統計
 */
function apiLogList(args) {
  const email = String(args.email || '').toLowerCase(), from = String(args.from || ''), to = String(args.to || ''), q = String(args.q || '').trim().toLowerCase();
  const limit = Math.min(+args.limit || 500, 2000);
  const all = readTable_('異動紀錄');
  const inRange = r => { const d = String(r.時間 || '').slice(0, 10); return (!from || d >= from) && (!to || d <= to); };
  const stat = {};
  const hit = [];
  for (let i = all.length - 1; i >= 0; i--) {
    const r = all[i];
    if (!inRange(r)) continue;
    const u = String(r.使用者 || '').toLowerCase();
    const s = stat[u] = stat[u] || { 使用者: r.使用者, 筆數: 0, 登入: 0, 最後時間: '' };
    s.筆數++; if (r.動作 === '登入') s.登入++; if (!s.最後時間) s.最後時間 = String(r.時間);
    if (email && u !== email) continue;
    if (q && (String(r.動作) + ' ' + String(r.案件編號) + ' ' + String(r.內容)).toLowerCase().indexOf(q) < 0) continue;
    if (hit.length < limit) hit.push(clean_(r));
  }
  const names = {}; readTable_('使用者').forEach(u => { names[String(u.Email).toLowerCase()] = u.姓名 || ''; });
  return { rows: hit, more: hit.length >= limit, stat: Object.keys(stat).map(k => Object.assign(stat[k], { 姓名: names[k] || '' })).sort((a, b) => b.筆數 - a.筆數) };
